SELECT *, LAG(temp_c, 2) OVER (PARTITION BY device_code ORDER BY humidity, id) AS prev_temp_c, LAST_VALUE(humidity, TRUE) OVER (PARTITION BY device_code ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_humidity, MIN(temp_c) OVER (PARTITION BY device_code) AS device_code_min_temp_c, LAG(pressure, 2) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS prev_pressure, LAG(pressure, 1) OVER (PARTITION BY device_code ORDER BY status_bits, id) AS prev_pressure_2 FROM device_readings;
